#include <vector>
#include <string>
#include <algorithm>
using namespace std;

class Solution {
public:
    int minOperations(vector<string>& logs) {
        int depth = 0;
        for (const string& log : logs) {
            if (log == "../") {
                depth = max(0, depth - 1);
            } else if (log != "./") {
                depth++;
            }
        }
        return depth;
    }
};

class Solution {
    public int minOperations(String[] logs) {
        int depth = 0;
        for (String log : logs) {
            if (log.equals("../")) {
                depth = Math.max(0, depth - 1);
            } else if (!log.equals("./")) {
                depth++;
            }
        }
        return depth;
    }
}

/**
 * @param {string[]} logs
 * @return {number}
 */
var minOperations = function(logs) {
    let depth = 0;
    for (const log of logs) {
        if (log === '../') {
            depth = Math.max(0, depth - 1);
        } else if (log !== './') {
            depth++;
        }
    }
    return depth;
};
